package com.nightbeam.donutshards.command;
import com.nightbeam.donutshards.model.*;import com.nightbeam.donutshards.scheduler.SchedulerService;import com.nightbeam.donutshards.service.MessageService;import com.nightbeam.donutshards.shop.ShopService;import com.nightbeam.donutshards.transaction.TransactionService;import com.nightbeam.donutshards.zone.ZoneService;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import java.util.stream.Collectors;
public final class CommandRouter implements CommandExecutor,TabCompleter {private final TransactionService tx;private final SchedulerService scheduler;private final MessageService messages;private final ZoneService zones;private final ShopService shop;private final AtomicInteger tax;private final Runnable reload;
 public CommandRouter(TransactionService tx,SchedulerService scheduler,MessageService messages,ZoneService zones,ShopService shop,AtomicInteger tax,Runnable reload){this.tx=tx;this.scheduler=scheduler;this.messages=messages;this.zones=zones;this.shop=shop;this.tax=tax;this.reload=reload;}
 public boolean onCommand(CommandSender sender,Command command,String label,String[] args){return switch(command.getName()){case "shards"->shards(sender,args);case "shardshop"->shop(sender);case "afk"->afk(sender,args);case "shardmanager"->admin(sender,args);default->false;};}
 private boolean shards(CommandSender s,String[] a){if(!(s instanceof Player p)){s.sendMessage("Players only.");return true;}if(a.length==0||a[0].equalsIgnoreCase("balance")){var target=p;if(a.length>1&&p.hasPermission("shards.balance.others")){var found=Bukkit.getPlayerExact(a[1]);if(found!=null)target=found;}var finalTarget=target;tx.balance(target.getUniqueId()).whenComplete((v,e)->reply(p,()->messages.send(p,e==null?"<gray><player>'s balance: <light_purple><balance></light_purple>":"<red>Database unavailable.</red>",e==null?Map.of("player",finalTarget.getName(),"balance",Long.toString(v)):Map.of())));return true;}if(a[0].equalsIgnoreCase("pay")&&a.length==3){var target=Bukkit.getPlayerExact(a[1]);var amount=parse(a[2]);if(target==null||amount<1){messages.send(p,"<red>Usage: /shards pay <online-player> <amount></red>",Map.of());return true;}var ctx=new MutationContext(TransactionType.PLAYER_TRANSFER,"player-transfer",p.getUniqueId(),"pay:"+UUID.randomUUID(),Map.of());tx.transfer(p.getUniqueId(),target.getUniqueId(),amount,tax.get(),ctx).whenComplete((r,e)->reply(p,()->messages.send(p,e==null&&r.success()?"<green>Sent <amount> shards to <player> (tax <tax>).</green>":"<red>Transfer failed: <reason></red>",e==null?Map.of("amount",Long.toString(amount),"player",target.getName(),"tax",Long.toString(r.tax()),"reason",r.reason()):Map.of("reason","storage_error"))));return true;}messages.send(p,"<gray>/shards balance [player] | /shards pay <player> <amount></gray>",Map.of());return true;}
 private boolean shop(CommandSender s){if(s instanceof Player p)shop.open(p);else s.sendMessage("Players only.");return true;}
 private boolean afk(CommandSender s,String[] a){if(!(s instanceof Player p)){s.sendMessage("Players only.");return true;}if(!zones.hasZones()){messages.send(p,"<gray>No AFK zones are configured yet.</gray>",Map.of());return true;}if(a.length==0){zones.syncPlayer(p);if(zones.current(p.getUniqueId()).isPresent())messages.send(p,"<green>You are in AFK zone <zone>.</green>",Map.of("zone",zones.current(p.getUniqueId()).get()));else messages.send(p,"<gray>Stand inside an AFK zone and use /afk join [name].</gray>",Map.of());return true;}return switch(a[0].toLowerCase(Locale.ROOT)){case "list"->{var names=zones.zones().stream().map(z->z.name()).sorted().collect(Collectors.joining(", "));messages.send(p,names.isBlank()?"<gray>No AFK zones configured.</gray>":"<gray>AFK zones: <light_purple><zones></light_purple></gray>",Map.of("zones",names));yield true;}case "join"->{if(a.length>=2){if(!zones.join(p,a[1]))messages.send(p,"<red>Could not join zone <zone>. Stand inside it first.</red>",Map.of("zone",a[1]));else messages.send(p,"<green>Joined AFK zone <zone>.</green>",Map.of("zone",zones.current(p.getUniqueId()).orElse(a[1])));}else{zones.syncPlayer(p);zones.current(p.getUniqueId()).ifPresentOrElse(z->messages.send(p,"<green>Joined AFK zone <zone>.</green>",Map.of("zone",z)),()->messages.send(p,"<red>Stand inside an AFK zone to join.</red>",Map.of()));}yield true;}case "leave"->{zones.leavePlayer(p).ifPresentOrElse(z->messages.send(p,"<gray>You left AFK zone <zone>.</gray>",Map.of("zone",z)),()->messages.send(p,"<gray>You are not in an AFK zone.</gray>",Map.of()));yield true;}case "info"->{zones.current(p.getUniqueId()).ifPresentOrElse(z->messages.send(p,"<gray>Current AFK zone: <light_purple><zone></light_purple></gray>",Map.of("zone",z)),()->messages.send(p,"<gray>You are not in an AFK zone.</gray>",Map.of()));yield true;}default->{messages.send(p,"<gray>/afk list | join [name] | leave | info</gray>",Map.of());yield true;}};}
 private boolean admin(CommandSender s,String[] a){if(!s.hasPermission("shards.admin")){messages.send(s,"<red>No permission.</red>",Map.of());return true;}if(a.length>=1&&a[0].equalsIgnoreCase("reload")){if(!s.hasPermission("shards.admin.reload")){messages.send(s,"<red>No permission.</red>",Map.of());return true;}reload.run();messages.send(s,"<green>DonutShards configuration reloaded.</green>",Map.of());return true;}if(a.length>=2&&a[0].equalsIgnoreCase("zone")){if(!s.hasPermission("shards.admin.zone")){messages.send(s,"<red>No permission.</red>",Map.of());return true;}return zoneAdmin(s,a);}if(a.length>=3&&(a[0].equalsIgnoreCase("give")||a[0].equalsIgnoreCase("take")||a[0].equalsIgnoreCase("set"))){var target=Bukkit.getOfflinePlayer(a[1]);var amount=parse(a[2]);if(amount<0){messages.send(s,"<red>Invalid amount.</red>",Map.of());return true;}var type=a[0].equalsIgnoreCase("give")?TransactionType.ADMIN_GIVE:a[0].equalsIgnoreCase("take")?TransactionType.ADMIN_TAKE:TransactionType.ADMIN_SET;var ctx=new MutationContext(type,"admin:"+a[0].toLowerCase(Locale.ROOT),s instanceof Player p?p.getUniqueId():null,"admin:"+UUID.randomUUID(),Map.of());var result=a[0].equalsIgnoreCase("give")?tx.add(target.getUniqueId(),amount,ctx):a[0].equalsIgnoreCase("take")?tx.remove(target.getUniqueId(),amount,ctx):tx.set(target.getUniqueId(),amount,ctx);result.whenComplete((r,e)->scheduler.global(()->s.sendMessage(e==null&&r.success()?"Balance updated.":"Update failed: "+(e==null?r.reason():"storage error"))));return true;}s.sendMessage("/shardmanager give|take|set <player> <amount> | reload | zone create|delete|list <name>");return true;}
 private boolean zoneAdmin(CommandSender s,String[] a){if(a.length<2){s.sendMessage("/shardmanager zone create|delete|list <name>");return true;}return switch(a[1].toLowerCase(Locale.ROOT)){case "list"->{if(zones.zones().isEmpty())s.sendMessage("No AFK zones configured.");else zones.zones().stream().map(z->z.name()+" @ "+z.world()+" ("+Math.round(z.x())+", "+Math.round(z.y())+", "+Math.round(z.z())+") r="+z.radius()).forEach(s::sendMessage);yield true;}case "create"->{if(!(s instanceof Player p)){s.sendMessage("Players only.");yield true;}if(a.length<3){s.sendMessage("Usage: /shardmanager zone create <name>");yield true;}try{if(zones.createZone(a[2],p.getLocation(),zones.defaultRadius()))s.sendMessage("Created AFK zone "+a[2]+" (radius "+zones.defaultRadius()+").");else s.sendMessage("Zone already exists or name is invalid.");}catch(Exception e){s.sendMessage("Could not save zone: "+e.getMessage());}yield true;}case "delete"->{if(a.length<3){s.sendMessage("Usage: /shardmanager zone delete <name>");yield true;}try{if(zones.deleteZone(a[2]))s.sendMessage("Deleted AFK zone "+a[2]+".");else s.sendMessage("Zone not found.");}catch(Exception e){s.sendMessage("Could not save zones: "+e.getMessage());}yield true;}default->{s.sendMessage("/shardmanager zone create|delete|list <name>");yield true;}};}
 private void reply(Player p,Runnable task){scheduler.entity(p,task,()->{});}private long parse(String text){try{return Long.parseLong(text);}catch(NumberFormatException e){return -1;}}
 public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(a.length==1)return c.getName().equals("shardmanager")?List.of("give","take","set","reset","reload","history","rollback","zone","migrate","debug","version","gui"):c.getName().equals("afk")?List.of("list","join","leave","info"):List.of("balance","pay","top","history","convert");if(a.length==2&&c.getName().equals("shardmanager")&&a[0].equalsIgnoreCase("zone"))return List.of("create","delete","list");if(a.length==3&&c.getName().equals("shardmanager")&&a[0].equalsIgnoreCase("zone")&&(a[1].equalsIgnoreCase("delete")||a[1].equalsIgnoreCase("join")))return zones.zones().stream().map(z->z.name()).toList();if(a.length==2&&c.getName().equals("afk")&&a[0].equalsIgnoreCase("join"))return zones.zones().stream().map(z->z.name()).toList();return List.of();}
}
